1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.web.bind.annotation.RequestBody;
6	
7	/**
8	 * First step of {@code POST /api/owners}: reads the request body once and normalizes the address in
9	 * place (trim and collapse whitespace, upper-case, expand common abbreviations — see
10	 * {@link OwnerAddressNormalizer}), then republishes the body for the rest of the pipeline. Running
11	 * before {@link RequireOwnerFields} means the required-field check sees the normalized address, so
12	 * an address that is blank after normalization is rejected; it also means the stored and returned
13	 * address, and every later address comparison, use the normalized form.
14	 */
15	public class NormalizeOwnerAddress {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated) {
18	        request.setAddress(OwnerAddressNormalizer.normalize(request.getAddress()));
19	        validated.set(request);
20	    }
21	}
