1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * The single duplicate check on {@code POST /api/owners}, keyed off the deterministic
11	 * {@link OwnerHousehold} householdId. Rejects with 409 via {@link DuplicateIdentityException} when
12	 * either:
13	 * <ul>
14	 * <li>the new owner's whole {@link OwnerIdentityKey} ({@code <telephone>|<email>|<householdId>})
15	 * equals an existing owner's — an exact duplicate; or</li>
16	 * <li>an existing owner shares the new owner's household (same {@code (lastName, postcode)}, hence
17	 * the same computed householdId) — a household duplicate. This is bypassed when the request opts in
18	 * with {@code sharesHousehold} true, in which case the owner is created as a declared household
19	 * member.</li>
20	 * </ul>
21	 * Runs before {@link BuildOwner} so no owner is created on conflict, and resolves the householdId
22	 * the request would receive so its key matches the one assigned and returned afterwards.
23	 */
24	public class CheckUniqueOwnerIdentity {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
27	            throws DuplicateIdentityException {
28	        String householdId = OwnerHousehold.householdId(request);
29	        String identityKey = OwnerIdentityKey.of(request.getTelephone(), request.getEmail(), householdId);
30	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
31	        for (Owner existing : ownerRepository.findAll()) {
32	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
33	                throw new DuplicateIdentityException(identityKey);
34	            }
35	            if (!sharesHousehold && householdId.equals(OwnerHousehold.householdId(existing))) {
36	                throw new DuplicateIdentityException(identityKey);
37	            }
38	        }
39	    }
40	}
