3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Runs on {@code POST /api/owners} before {@link BuildOwner} (so no owner is created on rejection):
11	 * rejects the request with 429 via {@link DailyOwnerLimitException} when {@link #MAX_OWNERS_PER_DAY}
12	 * or more owners have already been registered on the current business day (by {@code
13	 * registrationDate}). Because a weekend registration date rolls forward to the next Monday (see
14	 * {@link BusinessDay}), the bucket is that adjusted business day, not the raw calendar day.
15	 */
16	public class CheckDailyOwnerLimit {
17	
18	    /** Maximum owners that may be registered in a single day; the next create is rejected. */
19	    static final int MAX_OWNERS_PER_DAY = 100;
20	
21	    public void service(OwnerRepository ownerRepository) throws DailyOwnerLimitException {
22	        LocalDate today = BusinessDay.rollForward(LocalDate.now());
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (today.equals(existing.getRegistrationDate()) && ++count >= MAX_OWNERS_PER_DAY) {
26	                throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
27	            }
28	        }
29	    }
30	}
