3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.function.common.Localities;
10	
11	/**
12	 * Assigns a new owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>} where REGION is the
13	 * region derived from the postcode alone ({@link Localities#ofPostcode}: NSW 2000-2099, VIC
14	 * 3000-3099, QLD 4000-4099, else {@code UNKNOWN}) and HASH8 is the first 8 UPPER-case hex characters
15	 * of the SHA-256 digest over {@code normalizedTelephone + lastName} (e.g. {@code NSW-3F9A0C71}).
16	 * There are no per-city sequence numbers: the identity is stable for a given telephone, surname and
17	 * region. Runs after {@link BuildOwner} maps the request (so the telephone is already the normalized
18	 * E.164 value) and before {@link SaveOwner} persists it; every downstream region-and-hash value (the
19	 * membership number and its check digit, the locality and the create audit record) flows from this
20	 * code.
21	 */
22	public class AssignOwnerCustomerCode {
23	
24	    public void service(@Val Owner owner) {
25	        String region = Localities.ofPostcode(owner.getPostcode());
26	        String hash8 = hash8(owner.getTelephone() + owner.getLastName());
27	        owner.setCustomerCode(region + "-" + hash8);
28	    }
29	
30	    /** First 8 UPPER-case hex characters of SHA-256 over the UTF-8 bytes of {@code input}. */
31	    private static String hash8(String input) {
32	        try {
33	            byte[] digest = MessageDigest.getInstance("SHA-256")
34	                    .digest(input.getBytes(StandardCharsets.UTF_8));
35	            StringBuilder hex = new StringBuilder(8);
36	            for (byte b : digest) {
37	                hex.append(String.format("%02X", b));
38	                if (hex.length() >= 8) {
39	                    break;
40	                }
41	            }
42	            return hex.substring(0, 8);
43	        }
44	        catch (NoSuchAlgorithmException ex) {
45	            throw new IllegalStateException("SHA-256 not available", ex);
46	        }
47	    }
48	}
