3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	
11	/**
12	 * The deterministic householdId shared by {@link CheckUniqueOwnerIdentity} (which needs the id a
13	 * request would receive to detect household duplicates and build its identity key) and
14	 * {@link AssignOwnerHousehold} (which assigns it). The id is the first 12 hex characters of
15	 * SHA-256 over {@code <normalizedLastName>|<postcode>}, so owners with the same last name and
16	 * postcode share it automatically without any owner having to opt in: the household is keyed on
17	 * {@code (lastName, postcode)}, not on an existing member's id. {@code sharesHousehold} no longer
18	 * creates the link; it only bypasses the duplicate block for a declared household member.
19	 */
20	final class OwnerHousehold {
21	
22	    private OwnerHousehold() {
23	    }
24	
25	    /** The householdId a request would be assigned, from its last name and postcode. */
26	    static String householdId(OwnerFieldsDto request) {
27	        return compute(request.getLastName(), request.getPostcode());
28	    }
29	
30	    /** The householdId an existing owner belongs to, computed the same way from its own fields. */
31	    static String householdId(Owner owner) {
32	        return compute(owner.getLastName(), owner.getPostcode());
33	    }
34	
35	    /** First 12 hex characters of SHA-256 over {@code <normalizedLastName>|<postcode>}. */
36	    private static String compute(String lastName, String postcode) {
37	        String key = normalizeName(lastName) + "|" + safe(postcode);
38	        try {
39	            byte[] digest = MessageDigest.getInstance("SHA-256")
40	                    .digest(key.getBytes(StandardCharsets.UTF_8));
41	            StringBuilder sb = new StringBuilder(12);
42	            for (int i = 0; i < 6; i++) {
43	                sb.append(String.format("%02X", digest[i]));
44	            }
45	            return sb.toString();
46	        }
47	        catch (NoSuchAlgorithmException ex) {
48	            throw new IllegalStateException("SHA-256 not available", ex);
49	        }
50	    }
51	
52	    private static String safe(String value) {
53	        return value == null ? "" : value;
54	    }
55	
56	    /** Lower-case and collapse runs of whitespace so comparison is case- and whitespace-insensitive. */
57	    private static String normalizeName(String value) {
58	        if (value == null) {
59	            return "";
60	        }
61	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
62	    }
63	}
