23	    /** The identity key for the given normalized telephone, email and householdId. */
24	    public static String of(String telephone, String email, String householdId) {
25	        return safe(telephone) + "|" + safe(email) + "|" + safe(householdId);
26	    }
27	
28	    private static String safe(String value) {
29	        return value == null ? "" : value;
30	    }
