3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	
6	/**
7	 * Business-day rules for owner registration. A registration date must fall on a business day:
8	 * when it lands on a Saturday or Sunday it rolls forward to the next Monday. Used both to adjust
9	 * the effective registration date (see {@link DefaultOwnerRegistrationDate}) and to bucket the
10	 * daily create-limit (see {@link CheckDailyOwnerLimit}) so both share one definition.
11	 */
12	final class BusinessDay {
13	
14	    private BusinessDay() {
15	    }
16	
17	    /** Roll {@code date} forward over Saturday/Sunday to the next Monday; a weekday is unchanged. */
18	    static LocalDate rollForward(LocalDate date) {
19	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
20	            date = date.plusDays(1);
21	        }
22	        return date;
23	    }
24	}
