8	/**
9	 * Shared accumulation path for the per-business-day owner-registration rules. Counts the owners
10	 * whose {@code registrationDate} falls on the current business day (weekends roll forward to the
11	 * next Monday, see {@link BusinessDay}), the same bucket used by both the daily create-limit
12	 * ({@link CheckDailyOwnerLimit}) and the bulk-signup warning surfaced on {@link org
13	 * .springframework.samples.petclinic.rest.dto.OwnerDto}.
14	 */
15	final class DailyOwnerRegistrations {
16	
17	    /** Owners beyond this on the current business day trigger the bulk-signup warning. */
18	    static final int BULK_SIGNUP_THRESHOLD = 80;
19	
20	    private DailyOwnerRegistrations() {
21	    }
22	
23	    /** Number of owners registered on the current business day. */
24	    static int countToday(OwnerRepository ownerRepository) {
25	        LocalDate today = BusinessDay.rollForward(LocalDate.now());
26	        int count = 0;
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (today.equals(existing.getRegistrationDate())) {
29	                count++;
30	            }
31	        }
32	        return count;
33	    }
34	
35	    /** True when more than {@link #BULK_SIGNUP_THRESHOLD} owners were created on the current business day. */
36	    static boolean bulkSignupWarning(OwnerRepository ownerRepository) {
37	        return countToday(ownerRepository) > BULK_SIGNUP_THRESHOLD;
38	    }
39	}
