1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's locality (canonical region). The postcode is preferred: the region is looked
7	 * up by postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the
8	 * postcode is absent or falls in no known range does it fall back to the fixed city-to-region
9	 * table. Anything unresolved maps to {@link #UNKNOWN}.
10	 *
11	 * <p>{@link #ofPostcode(String)} resolves the region from the postcode alone — the {@code REGION}
12	 * segment of an owner's {@code customerCode} — and {@link #regionOf(String)} reads that segment
13	 * back out of a stored {@code customerCode}.
14	 */
15	public final class Localities {
16	
17	    /** Value returned when neither the postcode nor the city resolves a region. */
18	    public static final String UNKNOWN = "UNKNOWN";
19	
20	    /** City -> canonical region. */
21	    private static final Map<String, String> CITY_REGION = Map.of(
22	            "Sydney", "NSW",
23	            "Melbourne", "VIC",
24	            "Brisbane", "QLD");
25	
26	    /** Region -> inclusive 4-digit postcode range {low, high}. */
27	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
28	            "NSW", new int[] {2000, 2099},
29	            "VIC", new int[] {3000, 3099},
30	            "QLD", new int[] {4000, 4099});
31	
32	    private Localities() {
33	    }
34	
35	    /**
36	     * The canonical region for {@code city} using only the city-to-region table, or
37	     * {@code UNKNOWN} when not in the table.
38	     */
39	    public static String of(String city) {
40	        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
41	    }
42	
43	    /**
44	     * The canonical region, preferring the postcode: resolves by postcode range first and only
45	     * falls back to the city-to-region table when the postcode is absent or in no known range.
46	     * Returns {@code UNKNOWN} when neither resolves.
47	     */
48	    public static String of(String city, String postcode) {
49	        String byPostcode = byPostcode(postcode);
50	        return byPostcode != null ? byPostcode : of(city);
51	    }
52	
53	    /**
54	     * The canonical region derived from the postcode ALONE (no city fallback): the region whose
55	     * range contains {@code postcode}, or {@code UNKNOWN} when the postcode is absent or in no known
56	     * range. This is the {@code REGION} segment of an owner's {@code customerCode}.
57	     */
58	    public static String ofPostcode(String postcode) {
59	        String byPostcode = byPostcode(postcode);
60	        return byPostcode != null ? byPostcode : UNKNOWN;
61	    }
62	
63	    /**
64	     * The region an owner belongs to, read back from the {@code REGION} segment of its
65	     * {@code customerCode} ({@code <REGION>-<HASH8>}) — the single region-and-hash identity all
66	     * region-derived values now flow from. Returns {@code UNKNOWN} when the code is absent or
67	     * unsegmented.
68	     */
69	    public static String regionOf(String customerCode) {
70	        if (customerCode == null) {
71	            return UNKNOWN;
72	        }
73	        int dash = customerCode.indexOf('-');
74	        return dash < 0 ? UNKNOWN : customerCode.substring(0, dash);
75	    }
76	
77	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
78	    private static String byPostcode(String postcode) {
79	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
80	            return null;
81	        }
82	        int value = Integer.parseInt(postcode);
83	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
84	            int[] range = entry.getValue();
85	            if (value >= range[0] && value <= range[1]) {
86	                return entry.getKey();
87	            }
88	        }
89	        return null;
90	    }
91	}
