69	    /**
70	     * Score the owner's membership points. Starts at 0, plus 2 when an email is present, plus 1
71	     * when {@code namesakeCount} is 0, plus 2 for a household of 3 or more owners, plus 3 when
72	     * tenure exceeds 365 days. Because a newly created owner has zero tenure, the tenure points
73	     * are only earned on later reads.
74	     */
75	    protected Integer membershipPoints(Owner owner) {
76	        int points = 0;
77	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
78	            points += 2;
79	        }
80	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount().intValue() == 0) {
81	            points += 1;
82	        }
83	        if (householdSize(owner) >= 3) {
84	            points += 2;
85	        }
86	        if (owner.getRegistrationDate() != null
87	                && java.time.temporal.ChronoUnit.DAYS.between(owner.getRegistrationDate(),
88	                        java.time.LocalDate.now()) > 365) {
89	            points += 3;
90	        }
91	        return points;
