163	    /**
164	     * Format the stored E.164 telephone for humans: the country code, a space, then the national
165	     * digits grouped in threes from the left (e.g. {@code +61412345678} -> {@code +61 412 345 678}).
166	     * Returns the raw value unchanged when it is not a recognised E.164 number.
167	     */
168	    protected String telephoneDisplay(Owner owner) {
169	        String telephone = owner.getTelephone();
170	        if (telephone == null || !telephone.startsWith("+")) {
171	            return telephone;
172	        }
173	        String digits = telephone.substring(1);
174	        String code = null;
175	        for (String candidate : COUNTRY_CODES) {
176	            if (digits.startsWith(candidate)) {
177	                code = candidate;
178	                break;
179	            }
180	        }
181	        if (code == null) {
182	            return telephone;
183	        }
184	        String national = digits.substring(code.length());
185	        StringBuilder grouped = new StringBuilder("+").append(code);
186	        for (int i = 0; i < national.length(); i += 3) {
187	            grouped.append(' ').append(national, i, Math.min(i + 3, national.length()));
188	        }
189	        return grouped.toString();
190	    }
