192	    /**
193	     * Compute a single Luhn check digit (0-9) over the digits contained in the owner's
194	     * {@code customerCode}. Non-digit characters (such as the hyphen separators) are ignored.
195	     */
196	    protected Integer checkDigit(Owner owner) {
197	        String code = owner.getCustomerCode();
198	        if (code == null) {
199	            return null;
200	        }
201	        int sum = 0;
202	        boolean dbl = true;
203	        for (int i = code.length() - 1; i >= 0; i--) {
204	            char c = code.charAt(i);
205	            if (c < '0' || c > '9') {
206	                continue;
207	            }
208	            int d = c - '0';
209	            if (dbl) {
210	                d *= 2;
211	                if (d > 9) {
212	                    d -= 9;
213	                }
214	            }
215	            sum += d;
216	            dbl = !dbl;
217	        }
218	        return (10 - (sum % 10)) % 10;
219	    }
